INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Brauche ich für ein LAN immer einen ISP?', 2, '[{"text": "Nein", "correct": true, "because": "LAN kann lokal funktionieren"}, {"text": "Ja", "correct": false, "because": "Nur für WAN-Zugang nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Adressen plane ich typischerweise für ein kleines LAN?', 3, '[{"text": "2^64", "correct": true, "because": "/64-Subnetz ist Standard"}, {"text": "2^32", "correct": false, "because": "IPv4-Größe"}, {"text": "2^128", "correct": false, "because": "Gesamter IPv6-Raum"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein ISP in der Netzwerkplanung?', 4, '[{"text": "Bereitstellung globaler Adressen", "correct": true, "because": "Verbindung zum WAN"}, {"text": "Lokale Subnetzverwaltung", "correct": false, "because": "LAN-intern"}, {"text": "Hardware-Konfiguration", "correct": false, "because": "Kundenaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) LAN nutzt oft /64-Subnetze. b) WAN erfordert einen ISP.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) Standard, b) für Internet"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung eines LAN?', 5, '[{"text": "Globale Routing-Tabellen", "correct": true, "because": "Nur lokal relevant"}, {"text": "Subnetzgröße", "correct": false, "because": "Definiert Adressraum"}, {"text": "Hostanzahl", "correct": false, "because": "Bestimmt Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein WAN ohne ISP möglich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Private WANs möglich"}, {"text": "Nein", "correct": false, "because": "Öffentliches WAN braucht ISP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Präfix wähle ich für ein großes WAN?', 3, '[{"text": "/48", "correct": true, "because": "Bietet viele Subnetze"}, {"text": "/64", "correct": false, "because": "Einzelnes Subnetz"}, {"text": "/128", "correct": false, "because": "Einzeladresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich bei der Netzwerkplanung?', 5, '[{"text": "Subnetzgröße", "correct": true, "because": "Definiert Adressraum"}, {"text": "ISP-Zugang", "correct": true, "because": "Für WAN nötig"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) LANs nutzen /64 für SLAAC. b) ISPs vergeben nur /64. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, oft /48 oder /56"}, {"text": "Beides stimmt", "correct": false, "because": "b) ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Planung eines LAN?', 4, '[{"text": "Subnetzgröße", "correct": false, "because": "Bestimmt Adressraum"}, {"text": "Hostanzahl", "correct": false, "because": "Definiert Bedarf"}, {"text": "Globale Routbarkeit", "correct": true, "because": "Nur lokal nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein ISP für ein kleines LAN nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Kann lokal laufen"}, {"text": "Ja", "correct": false, "because": "Nur für Internet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten plane ich für ein WAN?', 4, '[{"text": "Globale Adressen", "correct": true, "because": "Für Internetzugang"}, {"text": "ISP-Verbindung", "correct": true, "because": "Bereitstellung"}, {"text": "Lokale Switches", "correct": false, "because": "LAN-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass LANs keine /48-Adressen brauchen. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "/64 reicht für ein LAN"}, {"text": "Nein", "correct": false, "because": "Große LANs könnten es nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Planung eines LAN?', 3, '[{"text": "Lokale Adresszuweisung", "correct": true, "because": "Effiziente Nutzung"}, {"text": "Globale Erreichbarkeit", "correct": false, "because": "Nicht primär"}, {"text": "Bandbreitenkosten", "correct": false, "because": "WAN-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) WAN braucht ISP-Adressen. b) LAN ist immer /64.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) flexibel, nicht immer /64"}, {"text": "Beides stimmt", "correct": false, "because": "b) ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Netzwerkplanung?', 5, '[{"text": "Effiziente Adressnutzung", "correct": true, "because": "Optimiert Ressourcen"}, {"text": "Skalierbarkeit", "correct": true, "because": "Wachstum möglich"}, {"text": "Minimale Subnetze", "correct": false, "because": "Flexibilität wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Planung eines WAN unwichtig?', 3, '[{"text": "ISP-Adressen", "correct": false, "because": "Für Zugang nötig"}, {"text": "Subnetzanzahl", "correct": false, "because": "Bestimmt Struktur"}, {"text": "LAN-Hardware", "correct": true, "because": "WAN-fremd"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein LAN ohne Internet laufen?', 2, '[{"text": "Ja", "correct": true, "because": "Lokal unabhängig"}, {"text": "Nein", "correct": false, "because": "Internet optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein ISP /48 für ein WAN vergibt?', 3, '[{"text": "Ja", "correct": true, "because": "Üblich für Organisationen"}, {"text": "Nein", "correct": false, "because": "Häufige Praxis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Präfix wähle ich für ein kleines LAN mit SLAAC?', 4, '[{"text": "/64", "correct": true, "because": "SLAAC-Standard"}, {"text": "/48", "correct": false, "because": "Zu groß für ein LAN"}, {"text": "/56", "correct": false, "because": "Nicht SLAAC-kompatibel"}]');
